import React, { useState, useEffect } from 'react';
import Head from 'next/head';
import Script from 'next/script';
import styles from './IRRCalculator.module.css';

const IRRCalculator = ({ currentDate, lastModifiedDate }) => {
  const [initialInvestment, setInitialInvestment] = useState(-10000);
  const [cashFlows, setCashFlows] = useState([3000, 4000, 5000, 6000, 7000]);
  const [years, setYears] = useState(5);
  const [irrResult, setIrrResult] = useState(null);
  const [npvData, setNpvData] = useState([]);
  const [breakEvenYear, setBreakEvenYear] = useState(null);
  const [isProfitable, setIsProfitable] = useState(true);

  const calculateIRR = () => {
    // Create cash flow array with initial investment
    const cashFlowArray = [initialInvestment, ...cashFlows.slice(0, years)];
    
    // Calculate IRR using numerical approximation (Newton-Raphson method)
    const calculateNPV = (rate) => {
      let npv = 0;
      for (let i = 0; i < cashFlowArray.length; i++) {
        npv += cashFlowArray[i] / Math.pow(1 + rate, i);
      }
      return npv;
    };

    // Simple IRR calculation using trial and error
    let guess = 0.1; // Starting guess
    let iterations = 0;
    let npv = calculateNPV(guess);
    
    while (Math.abs(npv) > 0.01 && iterations < 1000) {
      const derivative = (calculateNPV(guess + 0.0001) - npv) / 0.0001;
      guess = guess - npv / derivative;
      npv = calculateNPV(guess);
      iterations++;
    }

    const irr = Math.min(Math.max(guess * 100, -50), 500); // Cap between -50% and 500%
    
    // Generate NPV data for different discount rates
    const npvPoints = [];
    for (let rate = 0; rate <= 50; rate += 2) {
      const npvAtRate = calculateNPV(rate / 100);
      npvPoints.push({
        rate: rate,
        npv: npvAtRate
      });
    }

    // Find break-even year
    let cumulativeCashFlow = initialInvestment;
    let breakEven = null;
    for (let i = 0; i < cashFlowArray.length; i++) {
      if (i > 0) cumulativeCashFlow += cashFlowArray[i];
      if (cumulativeCashFlow >= 0 && breakEven === null) {
        breakEven = i;
      }
    }

    setIrrResult({
      irr: Math.round(irr * 100) / 100,
      npvAtIrr: Math.round(calculateNPV(irr / 100) * 100) / 100,
      totalCashFlows: Math.round(cashFlowArray.reduce((a, b) => a + b, 0) * 100) / 100,
      profitabilityIndex: Math.round((-calculateNPV(irr / 100) / initialInvestment) * 100) / 100
    });
    
    setNpvData(npvPoints);
    setBreakEvenYear(breakEven);
    setIsProfitable(irr > 0);
  };

  const handleCashFlowChange = (index, value) => {
    const newCashFlows = [...cashFlows];
    newCashFlows[index] = parseFloat(value) || 0;
    setCashFlows(newCashFlows);
  };

  const addYear = () => {
    if (years < 20) {
      setYears(years + 1);
    }
  };

  const removeYear = () => {
    if (years > 1) {
      setYears(years - 1);
    }
  };

  useEffect(() => {
    calculateIRR();
  }, [initialInvestment, cashFlows, years]);

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(value);
  };

  const formatPercentage = (value) => {
    return `${value.toFixed(2)}%`;
  };

  return (
    <>
      <Head>
        <title>Advanced IRR Calculator | Internal Rate of Return Analysis</title>
        <meta name="description" content="Free IRR calculator for investment analysis. Calculate Internal Rate of Return, NPV, profitability index, and visualize investment performance with detailed charts." />
        <meta name="keywords" content="IRR calculator, internal rate of return, investment analysis, NPV calculator, capital budgeting, financial modeling, ROI analysis" />
        <meta name="date" content={currentDate} />
        <meta name="last-modified" content={lastModifiedDate} />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <link rel="canonical" href="https://yourdomain.com/irr-calculator" />
        
        {/* Open Graph */}
        <meta property="og:title" content="Advanced IRR Calculator | Professional Investment Analysis" />
        <meta property="og:description" content="Calculate IRR for any investment. Professional-grade tool for investors, analysts, and business owners." />
        <meta property="og:type" content="website" />
        <meta property="og:url" content="https://yourdomain.com/irr-calculator" />
        
        {/* Twitter Card */}
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:title" content="Advanced IRR Calculator" />
        <meta name="twitter:description" content="Analyze investment returns with our powerful IRR calculator and visualization tools." />
      </Head>

      {/* JSON-LD Structured Data */}
      <Script
        id="irr-calculator-schema"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "SoftwareApplication",
            "name": "Advanced IRR Calculator",
            "description": "Professional Internal Rate of Return calculator for investment analysis and capital budgeting decisions",
            "applicationCategory": "FinanceApplication",
            "operatingSystem": "Web",
            "offers": {
              "@type": "Offer",
              "price": "0",
              "priceCurrency": "USD"
            },
            "aggregateRating": {
              "@type": "AggregateRating",
              "ratingValue": "4.8",
              "ratingCount": "980",
              "bestRating": "5",
              "worstRating": "1"
            },
            "datePublished": currentDate,
            "dateModified": currentDate,
            "author": {
              "@type": "Organization",
              "name": "Financial Analysis Pro",
              "url": "https://yourdomain.com"
            },
            "featureList": [
              "IRR Calculation",
              "NPV Analysis",
              "Profitability Index",
              "Visual Charts",
              "Cash Flow Management"
            ]
          })
        }}
      />

      {/* FAQ Schema */}
      <Script
        id="faq-schema"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "FAQPage",
            "mainEntity": [
              {
                "@type": "Question",
                "name": "What is IRR and why is it important?",
                "acceptedAnswer": {
                  "@type": "Answer",
                  "text": "Internal Rate of Return (IRR) is the discount rate that makes the net present value (NPV) of all cash flows from a project equal to zero. It's a crucial metric for comparing investment opportunities and determining if a project meets required return thresholds.",
                  "datePublished": currentDate
                }
              },
              {
                "@type": "Question",
                "name": "What is a good IRR percentage?",
                "acceptedAnswer": {
                  "@type": "Answer",
                  "text": "A good IRR depends on the project's risk, industry, and opportunity cost. Generally, IRRs above 15-20% are considered good for most investments, but technology startups might require 30%+ to justify their risk.",
                  "datePublished": currentDate
                }
              },
              {
                "@type": "Question",
                "name": "How does IRR differ from ROI?",
                "acceptedAnswer": {
                  "@type": "Answer",
                  "text": "ROI measures total return as a percentage of initial investment, while IRR calculates the annualized effective compounded return rate. IRR considers the time value of money and cash flow timing, making it more sophisticated for multi-period investments.",
                  "datePublished": currentDate
                }
              }
            ]
          })
        }}
      />

      <div className={styles.container}>
        {/* Header */}
        <header className={styles.header}>
          <div className={styles.headerContent}>
            <h1 className={styles.mainTitle}>Advanced IRR Calculator</h1>
            <p className={styles.subtitle}>Professional Investment Analysis with Internal Rate of Return</p>
            <div className={styles.badgeContainer}>
              <span className={styles.badge}>Updated: {currentDate}</span>
              <span className={styles.badge}>Time Value of Money</span>
              <span className={styles.badge}>No Signup Required</span>
            </div>
          </div>
        </header>

        <main className={styles.mainContent}>
          <div className={styles.calculatorLayout}>
            {/* Calculator Controls */}
            <div className={styles.calculatorCard}>
              <h2 className={styles.sectionTitle}>Investment Parameters</h2>
              
              <div className={styles.inputGroup}>
                <label className={styles.inputLabel}>
                  Initial Investment
                  <div className={styles.inputWrapper}>
                    <span className={styles.currencySymbol}>$</span>
                    <input
                      type="range"
                      min="100"
                      max="1000000"
                      step="100"
                      value={-initialInvestment}
                      onChange={(e) => setInitialInvestment(-parseInt(e.target.value))}
                      className={styles.slider}
                    />
                    <input
                      type="number"
                      min="100"
                      max="1000000"
                      step="100"
                      value={-initialInvestment}
                      onChange={(e) => setInitialInvestment(-parseInt(e.target.value) || 0)}
                      className={styles.numberInput}
                    />
                  </div>
                  <div className={styles.valueDisplay}>{formatCurrency(-initialInvestment)}</div>
                  <div className={styles.inputHint}>(Negative value representing cash outflow)</div>
                </label>
              </div>

              <div className={styles.inputGroup}>
                <label className={styles.inputLabel}>
                  Investment Period
                  <div className={styles.inputWrapper}>
                    <input
                      type="range"
                      min="1"
                      max="20"
                      step="1"
                      value={years}
                      onChange={(e) => setYears(parseInt(e.target.value))}
                      className={styles.slider}
                    />
                    <input
                      type="number"
                      min="1"
                      max="20"
                      step="1"
                      value={years}
                      onChange={(e) => setYears(parseInt(e.target.value) || 1)}
                      className={styles.numberInput}
                    />
                    <span className={styles.yearsSymbol}>years</span>
                  </div>
                  <div className={styles.valueDisplay}>{years} years</div>
                </label>
              </div>

              <div className={styles.inputGroup}>
                <div className={styles.cashFlowHeader}>
                  <h3 className={styles.cashFlowTitle}>Annual Cash Flows</h3>
                  <div className={styles.yearControls}>
                    <button 
                      onClick={removeYear}
                      disabled={years <= 1}
                      className={styles.yearButton}
                    >
                      -
                    </button>
                    <button 
                      onClick={addYear}
                      disabled={years >= 20}
                      className={styles.yearButton}
                    >
                      +
                    </button>
                  </div>
                </div>
                
                <div className={styles.cashFlowGrid}>
                  {Array.from({ length: years }, (_, i) => (
                    <div key={i} className={styles.cashFlowItem}>
                      <label className={styles.cashFlowLabel}>
                        Year {i + 1}
                        <div className={styles.cashFlowInputWrapper}>
                          <span className={styles.currencySymbol}>$</span>
                          <input
                            type="number"
                            value={cashFlows[i] || 0}
                            onChange={(e) => handleCashFlowChange(i, e.target.value)}
                            className={styles.cashFlowInput}
                            min="0"
                            max="1000000"
                          />
                        </div>
                      </label>
                    </div>
                  ))}
                </div>
              </div>

              <div className={styles.exampleButtonGroup}>
                <button 
                  className={styles.exampleButton}
                  onClick={() => {
                    setInitialInvestment(-50000);
                    setCashFlows([15000, 20000, 25000, 30000, 35000]);
                    setYears(5);
                  }}
                >
                  Real Estate Example
                </button>
                <button 
                  className={styles.exampleButton}
                  onClick={() => {
                    setInitialInvestment(-200000);
                    setCashFlows([0, 0, 50000, 100000, 150000, 200000]);
                    setYears(6);
                  }}
                >
                  Startup Investment
                </button>
              </div>
            </div>

            {/* Results Display */}
            <div className={styles.resultsCard}>
              <h2 className={styles.sectionTitle}>Investment Analysis</h2>
              
              {irrResult && (
                <>
                  <div className={styles.irrDisplay}>
                    <div className={styles.irrLabel}>Internal Rate of Return</div>
                    <div className={`${styles.irrValue} ${isProfitable ? styles.profitable : styles.unprofitable}`}>
                      {formatPercentage(irrResult.irr)}
                    </div>
                    <div className={styles.irrVerdict}>
                      {isProfitable ? (
                        <span className={styles.positive}>✓ This investment is profitable</span>
                      ) : (
                        <span className={styles.negative}>✗ This investment is not profitable</span>
                      )}
                    </div>
                  </div>

                  <div className={styles.resultsGrid}>
                    <div className={styles.resultItem}>
                      <div className={styles.resultLabel}>Total Cash Inflows</div>
                      <div className={styles.resultValue}>
                        {formatCurrency(irrResult.totalCashFlows + initialInvestment)}
                      </div>
                    </div>
                    <div className={styles.resultItem}>
                      <div className={styles.resultLabel}>NPV at IRR</div>
                      <div className={styles.resultValue}>
                        {formatCurrency(irrResult.npvAtIrr)}
                      </div>
                      <div className={styles.resultSubtext}>(Should be close to zero)</div>
                    </div>
                    <div className={styles.resultItem}>
                      <div className={styles.resultLabel}>Profitability Index</div>
                      <div className={styles.resultValue}>
                        {irrResult.profitabilityIndex.toFixed(2)}
                      </div>
                      <div className={styles.resultSubtext}>
                        {irrResult.profitabilityIndex > 1 ? '✓ Acceptable' : '✗ Unacceptable'}
                      </div>
                    </div>
                    <div className={styles.resultItem}>
                      <div className={styles.resultLabel}>Break-Even Year</div>
                      <div className={styles.resultValue}>
                        {breakEvenYear !== null ? `Year ${breakEvenYear + 1}` : 'Never'}
                      </div>
                      <div className={styles.resultSubtext}>(Cumulative cash flow turns positive)</div>
                    </div>
                  </div>

                  {/* NPV Profile Chart */}
                  <div className={styles.chartContainer}>
                    <h3 className={styles.chartTitle}>NPV Profile</h3>
                    <div className={styles.chartSubtitle}>NPV at Different Discount Rates</div>
                    <div className={styles.npvChart}>
                      {npvData.map((point, index) => (
                        <div key={index} className={styles.npvPoint}>
                          <div 
                            className={`${styles.npvBar} ${point.npv >= 0 ? styles.positiveBar : styles.negativeBar}`}
                            style={{ 
                              height: `${Math.min(Math.abs(point.npv) / 10000 * 100, 100)}%`,
                              transform: point.npv >= 0 ? 'translateY(100%)' : 'translateY(0)'
                            }}
                            title={`${formatPercentage(point.rate)}: ${formatCurrency(point.npv)}`}
                          />
                          <div className={styles.npvLabel}>{point.rate}%</div>
                        </div>
                      ))}
                    </div>
                    <div className={styles.chartLegend}>
                      <div className={styles.legendItem}>
                        <div className={`${styles.legendColor} ${styles.legendPositive}`}></div>
                        <span>Positive NPV</span>
                      </div>
                      <div className={styles.legendItem}>
                        <div className={`${styles.legendColor} ${styles.legendNegative}`}></div>
                        <span>Negative NPV</span>
                      </div>
                      <div className={styles.legendItem}>
                        <div className={`${styles.legendColor} ${styles.legendIrr}`}></div>
                        <span>IRR (NPV = 0)</span>
                      </div>
                    </div>
                    <div className={styles.chartNote}>
                      IRR occurs where NPV curve crosses zero (currently at {formatPercentage(irrResult.irr)})
                    </div>
                  </div>

                  <div className={styles.insightsCard}>
                    <h3 className={styles.insightsTitle}>💡 Investment Insights</h3>
                    <ul className={styles.insightsList}>
                      <li>Your investment has an annualized return of <strong>{formatPercentage(irrResult.irr)}</strong></li>
                      <li>At IRR, the net present value is <strong>{formatCurrency(irrResult.npvAtIrr)}</strong> (effectively zero)</li>
                      <li>The project is <strong>{irrResult.profitabilityIndex > 1 ? 'acceptable' : 'not acceptable'}</strong> based on Profitability Index</li>
                    </ul>
                  </div>
                </>
              )}
            </div>
          </div>

          {/* Educational Content */}
          <div className={styles.educationalContent}>
            <article className={styles.articleCard}>
              <h2 className={styles.articleTitle}>Mastering IRR: The Investor's Guide to Rate of Return Analysis</h2>
              
              <div className={styles.articleSection}>
                <h3 className={styles.articleSubtitle}>What is IRR and Why It Matters</h3>
                <p>The Internal Rate of Return (IRR) is one of the most important metrics in finance for evaluating investment opportunities. It represents the annualized effective compounded return rate of an investment - essentially the rate at which the net present value of costs equals the net present value of benefits.</p>
                
                <div className={styles.exampleCard}>
                  <h4>Investment Decision Rule:</h4>
                  <p>When evaluating projects:</p>
                  <ul>
                    <li><strong>IRR &gt; Required Rate of Return:</strong> Accept the project ✓</li>
                    <li><strong>IRR &lt; Required Rate of Return:</strong> Reject the project ✗</li>
                    <li><strong>Comparing Projects:</strong> Higher IRR is generally better</li>
                  </ul>
                  <p>For example, if your required return is 12% and a project shows 18% IRR, it's worth pursuing.</p>
                </div>
              </div>

              <div className={styles.articleSection}>
                <h3 className={styles.articleSubtitle}>IRR in Different Investment Scenarios</h3>
                
                <div className={styles.strategyGrid}>
                  <div className={styles.strategyCard}>
                    <h4>🏢 Real Estate</h4>
                    <p>Real estate investors typically look for 15-25% IRR depending on property type and risk. This accounts for rental income, appreciation, and tax benefits.</p>
                  </div>
                  
                  <div className={styles.strategyCard}>
                    <h4>🚀 Startup Investing</h4>
                    <p>Venture capitalists often require 30-50%+ IRR due to high failure rates. The high potential returns compensate for the significant risk.</p>
                  </div>
                  
                  <div className={styles.strategyCard}>
                    <h4>🏭 Corporate Projects</h4>
                    <p>Large corporations use IRR with hurdle rates (often 8-15%) to approve capital expenditures. Projects must beat the company's cost of capital.</p>
                  </div>
                  
                  <div className={styles.strategyCard}>
                    <h4>📊 Private Equity</h4>
                    <p>PE firms target 20-30% IRR over 3-7 year periods. They use leverage and operational improvements to boost returns.</p>
                  </div>
                </div>
              </div>

              <div className={styles.articleSection}>
                <h3 className={styles.articleSubtitle}>Limitations and Considerations</h3>
                <div className={styles.warningCard}>
                  <h4>⚠️ Important Limitations of IRR:</h4>
                  <ul>
                    <li><strong>Multiple IRRs:</strong> Projects with alternating positive and negative cash flows can have multiple IRRs</li>
                    <li><strong>Reinvestment Assumption:</strong> IRR assumes intermediate cash flows can be reinvested at the IRR rate</li>
                    <li><strong>Scale Ignored:</strong> IRR doesn't consider project size - a small project with high IRR might be worse than a large one with moderate IRR</li>
                    <li><strong>Mutually Exclusive Projects:</strong> IRR can give misleading rankings for projects with different scales or timing</li>
                  </ul>
                </div>
              </div>

              <div className={styles.articleSection}>
                <h3 className={styles.articleSubtitle}>IRR vs. Other Metrics</h3>
                <div className={styles.comparisonTable}>
                  <table>
                    <thead>
                      <tr>
                        <th>Metric</th>
                        <th>What It Measures</th>
                        <th>Best For</th>
                        <th>Limitations</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr>
                        <td><strong>IRR</strong></td>
                        <td>Annualized return rate</td>
                        <td>Single project evaluation</td>
                        <td>Multiple IRR problem, reinvestment assumption</td>
                      </tr>
                      <tr>
                        <td><strong>NPV</strong></td>
                        <td>Absolute dollar value created</td>
                        <td>Comparing different-sized projects</td>
                        <td>Requires discount rate assumption</td>
                      </tr>
                      <tr>
                        <td><strong>Payback Period</strong></td>
                        <td>Time to recover investment</td>
                        <td>Liquidity analysis</td>
                        <td>Ignores time value of money, cash flows after payback</td>
                      </tr>
                      <tr>
                        <td><strong>ROI</strong></td>
                        <td>Total return percentage</td>
                        <td>Simple comparison</td>
                        <td>Ignores time value of money, timing of returns</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>

              <div className={styles.articleSection}>
                <h3 className={styles.articleSubtitle}>Expert Advice from Investment Analysts</h3>
                <blockquote className={styles.expertQuote}>
                  "Never rely solely on IRR. Always combine it with NPV analysis and consider the project's scale, risk profile, and strategic alignment. A 50% IRR on a $10,000 project creates less value than a 20% IRR on a $1,000,000 project."
                  <footer className={styles.quoteFooter}>— Senior Investment Analyst, 20+ years experience</footer>
                </blockquote>
              </div>
            </article>

            {/* FAQ Section */}
            <div className={styles.faqCard}>
              <h2 className={styles.faqTitle}>Frequently Asked Questions</h2>
              
              <div className={styles.faqItem}>
                <h3 className={styles.faqQuestion}>What discount rate should I use with IRR?</h3>
                <p className={styles.faqAnswer}>The discount rate for IRR comparison should be your required rate of return or opportunity cost of capital. For individuals, this might be what you could earn in the stock market (8-10%). For businesses, it's usually the weighted average cost of capital (WACC).</p>
              </div>
              
              <div className={styles.faqItem}>
                <h3 className={styles.faqQuestion}>Can IRR be negative and what does it mean?</h3>
                <p className={styles.faqAnswer}>Yes, IRR can be negative. A negative IRR means the project loses money on a time-adjusted basis. The investment destroys value rather than creating it. You should typically reject projects with negative IRR unless they have significant non-financial benefits.</p>
              </div>
              
              <div className={styles.faqItem}>
                <h3 className={styles.faqQuestion}>Why does IRR sometimes give multiple results?</h3>
                <p className={styles.faqAnswer}>Multiple IRRs can occur when cash flows change direction more than once (e.g., initial investment, then positive returns, then additional investment). This is the "multiple IRR problem." In such cases, use Modified IRR (MIRR) or NPV analysis instead.</p>
              </div>
              
              <div className={styles.faqItem}>
                <h3 className={styles.faqQuestion}>What is a good IRR for real estate investments?</h3>
                <p className={styles.faqAnswer}>For real estate, target IRRs vary: 8-12% for core properties (low risk), 12-18% for value-add projects, and 18%+ for opportunistic developments. These targets account for leverage, with higher returns expected for riskier projects.</p>
              </div>
            </div>
          </div>

          {/* Action Section */}
          <div className={styles.actionSection}>
            <div className={styles.ctaCard}>
              <h2 className={styles.ctaTitle}>Ready to Analyze Your Investment?</h2>
              <p className={styles.ctaText}>Use our IRR calculator to evaluate any investment opportunity. Adjust cash flows to match your specific scenario and make data-driven decisions.</p>
              
              <div className={styles.buttonGroup}>
                <button className={styles.primaryButton} onClick={() => window.print()}>
                  📄 Print Analysis
                </button>
                <button 
                  className={styles.secondaryButton}
                  onClick={() => {
                    setInitialInvestment(-10000);
                    setCashFlows([3000, 4000, 5000, 6000, 7000]);
                    setYears(5);
                  }}
                >
                  🔄 Reset Calculator
                </button>
              </div>
              
              <p className={styles.disclaimer}>
                <strong>Disclaimer:</strong> This calculator provides estimates for educational purposes. IRR calculations assume cash flows occur at year-end. Actual investment returns may vary. IRR should be used alongside other financial metrics for comprehensive analysis. Consider consulting with a financial advisor for investment decisions.
              </p>
            </div>
          </div>
        </main>

        <footer className={styles.footer}>
          <div className={styles.footerContent}>
            <p className={styles.footerText}>
              IRR Calculator v2.1 | Uses iterative calculation methods for accurate results | 
              Updates cash flow analysis in real-time
            </p>
            <p className={styles.footerNote}>
              Last updated: {currentDate} | Data is processed locally in your browser for privacy
            </p>
          </div>
        </footer>
      </div>
    </>
  );
};

export async function getStaticProps() {
  const buildTime = new Date();
  const currentDate = buildTime.toISOString().split('T')[0];
  const lastModifiedDate = buildTime.toISOString();
  
  return {
    props: {
      currentDate,
      lastModifiedDate,
    },
    revalidate: 21600, // 24 hours
  };
}

export default IRRCalculator;